            new Quote { Id = "https://ar.wikiquote.org/wiki/توفيق_الحكيم", Text = "إذا أردت أن تصمد للحياة فلا تأخذها على أنها مأساة.", Author = "توفيق الحكيم" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/توفيق_الحكيم", Text = "كثير من الناس يعيشون طويلا في الماضي، والماضي منصة للقفز لا أريكة للاسترخاء.", Author = "توفيق الحكيم" },
