            new Quote { Id = "https://ar.wikiquote.org/wiki/توفيق_الحكيم", Text = "إن عقل المرأة إذا ذبل ومات ،فقد ذبل عقل الأمة كلها ومات.", Author = "توفيق الحكيم" },
