            new Quote { Id = "https://ar.wikiquote.org/wiki/توفيق_الحكيم", Text = "الزواج نقلة مفاجئة من التدليل إلى التذليل.", Author = "توفيق الحكيم" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/توفيق_الحكيم", Text = "النهاية تتلوها البداية في قانون الأبدية والدوران.", Author = "توفيق الحكيم" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/توفيق_الحكيم", Text = "ما أنا إلا .. ماء ! هل لي وجود حقيقي خارج ما يحتوي جسدي من زمان ومكان حتى السفر أو الإنتقال إن هو إلا تغيير إناء بعد إناء , ومتى كان في تغيير الإناء تحرير الماء !", Author = "توفيق الحكيم" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/توفيق_الحكيم", Text = "لسنا حلماً .. لا بل الزمن هو الحلم .. أما نحن فحقيقة .. وهو الظل الزائل ونحن الباقون .. بل هو حلمنا .", Author = "توفيق الحكيم" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/توفيق_الحكيم", Text = "لقد فات زمننا ، ونحن الآن ملك التاريخ .. ولقد أردنا العودة إلى الزمن ، ولكن التاريخ ينتقم .", Author = "توفيق الحكيم" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/توفيق_الحكيم", Text = "الخيال هو ليل الحياة الجميل.. هو حصننا وملاذنا من قسوة النهار الطويل. إن عالم الواقع لا يكفي وحده لحياة البشر.. إنه أضيق من أن يتسع لحياة إنسانية كاملة.", Author = "توفيق الحكيم" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/توفيق_الحكيم", Text = "ما أشقى الآدميين! لقد كتب عليهم العمي وهم يحسبون أن لهم عيوناً مبصرة، إنا لا نبصر حقيقة الأشياء إلاّ بعيوننا الداخلية، ولا ندرك حقيقة الأمور إلاّ باتصالها، واصطدامها بجوهر مشاعرنا.", Author = "توفيق الحكيم" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/توفيق_الحكيم", Text = "إن مركبة الحياة كذلك لا يهوّن من أوجاعها غير أن يربط إليها شريكان يشدان عجلاتها.. ويشجع أحدهما الآخر كلّما سلّط عليه القدر سوطاً من سياطه.", Author = "توفيق الحكيم" },
            new Quote { Id = "https://ar.wikiquote.org/wiki/توفيق_الحكيم", Text = "أملي أكبر من جهدي.. وجهدي أكبر من موهبتي.. وموهبتي سجينة طبعي.. ولكنّي أقاوم.", Author = "توفيق الحكيم" },
